import type { Readable } from 'node:stream';
import type { HealthCheckResult } from './ports.js';

export type FileVisibility = 'private' | 'public';
export type FileStatus = 'pending' | 'ready';
export type FileMetadataValue = string | number | boolean | null;
export type FileMetadata = Record<string, FileMetadataValue>;

/** Metadata of one stored file. Timestamps are epoch milliseconds. */
export interface FileRecord {
  id: string;
  /** Object key inside the driver. Generated by the service unless a trusted caller sets it. */
  key: string;
  /** Sanitised original filename. */
  filename: string;
  /** Effective content type (verified by sniffing where a signature exists). */
  contentType: string;
  /** Content type declared by the uploader (after normalisation), if any. */
  declaredType?: string;
  /** Content type detected from magic bytes, if recognised. */
  detectedType?: string;
  /** Size in bytes. For pending uploads this is the declared size or 0. */
  size: number;
  /** Lowercase hex SHA-256 of the content. Absent while pending. */
  sha256?: string;
  ownerId?: string;
  tenantId?: string;
  visibility: FileVisibility;
  metadata: FileMetadata;
  status: FileStatus;
  /** Bytes reserved against quotas while pending. 0 once ready. */
  reservedBytes: number;
  /** Pending uploads expire at this time and are released by cleanupExpired(). */
  expiresAt?: number;
  createdAt: number;
  updatedAt: number;
}

/** Resumable upload session. The session ID equals the pending file ID. */
export interface UploadSession {
  id: string;
  uploadLength: number;
  uploadOffset: number;
  /** Driver-specific JSON state (for example S3 multipart upload ID and parts). */
  driverState: Record<string, unknown>;
  /** 'resumable' for chunked sessions, 'signed-put' for adapter signed PUT URLs. */
  kind: 'resumable' | 'signed-put';
  lockToken?: string;
  lockedUntil?: number;
  expiresAt: number;
  createdAt: number;
  updatedAt: number;
}

export type QuotaScopeType = 'owner' | 'tenant';

export interface QuotaScope {
  type: QuotaScopeType;
  id: string;
}

export interface QuotaLimit {
  maxBytes?: number;
  maxFiles?: number;
}

export interface QuotaUsage {
  scope: QuotaScope;
  bytesUsed: number;
  filesUsed: number;
  bytesReserved: number;
  filesReserved: number;
}

export interface ReservationRequest {
  /** Bytes to reserve. With exact=false the store reserves min(bytes, remaining quota). */
  bytes: number;
  exact: boolean;
  /**
   * Limits for the scopes of the file (owner from ownerId, tenant from tenantId). Scopes
   * without a limit are still tracked.
   */
  limits: Partial<Record<QuotaScopeType, QuotaLimit>>;
}

export interface CommitUpdate {
  size: number;
  sha256: string;
  contentType: string;
  detectedType?: string;
  updatedAt: number;
}

export interface FileUpdate {
  filename?: string;
  visibility?: FileVisibility;
  metadata?: FileMetadata;
  updatedAt: number;
}

export interface ListFilesQuery {
  ownerId?: string;
  tenantId?: string;
  /** Default 'ready'. */
  status?: FileStatus | 'all';
  /** 1 to 1000, default 100. */
  limit?: number;
  cursor?: string;
}

export interface ListFilesResult {
  items: FileRecord[];
  nextCursor?: string;
}

export type SessionLockResult = 'locked' | 'not_found' | 'offset_mismatch' | 'busy';

export interface SessionLockRequest {
  expectedOffset: number;
  token: string;
  until: number;
  now: number;
}

export interface SessionPatch {
  uploadOffset?: number;
  driverState?: Record<string, unknown>;
  lockedUntil?: number;
  updatedAt: number;
}

/**
 * Persists file metadata, upload sessions and quota usage. Methods that change quota usage
 * are atomic (a SQL transaction or a synchronous memory update).
 */
export interface StorageMetadataStore {
  /**
   * Reserves quota for every scope and inserts a pending file (and optional session) in one
   * atomic step. Throws StorageError STORAGE_QUOTA_EXCEEDED when a limit would be exceeded.
   */
  insertPending(
    file: FileRecord,
    reservation: ReservationRequest,
    session?: UploadSession,
  ): Promise<{ reservedBytes: number }>;
  /** Marks a pending file ready, converts its reservation into usage and removes its session. */
  commit(id: string, update: CommitUpdate): Promise<FileRecord>;
  /** Removes a pending file and its session and releases its reservation. */
  release(id: string): Promise<FileRecord | undefined>;
  get(id: string): Promise<FileRecord | undefined>;
  list(query: ListFilesQuery): Promise<ListFilesResult>;
  update(id: string, patch: FileUpdate): Promise<FileRecord | undefined>;
  /** Removes a ready file and decrements usage. Returns undefined when nothing was removed. */
  remove(id: string): Promise<FileRecord | undefined>;
  usage(scope: QuotaScope): Promise<QuotaUsage>;
  getSession(id: string): Promise<UploadSession | undefined>;
  lockSession(id: string, request: SessionLockRequest): Promise<SessionLockResult>;
  /** Updates a session. With lockToken the update applies only while that lock is held. */
  updateSession(id: string, patch: SessionPatch, lockToken?: string): Promise<boolean>;
  unlockSession(id: string, lockToken: string): Promise<void>;
  /** Pending files whose expiresAt is at or before now. */
  listExpired(now: number, limit: number): Promise<FileRecord[]>;
  ping?(): Promise<void>;
}

export interface ByteRange {
  /** First byte, inclusive. */
  start: number;
  /** Last byte, inclusive. */
  end: number;
}

export interface DriverPutOptions {
  contentType: string;
  /** Known size in bytes, when the caller knows it. */
  size?: number;
  signal?: AbortSignal;
}

export interface DriverObject {
  body: Readable;
  /** Total object size in bytes (not the range length). */
  size: number;
}

export interface PresignOptions {
  method: 'GET' | 'PUT';
  expiresInSeconds: number;
  contentType?: string;
  contentDisposition?: string;
  /** Base64 SHA-256 the uploader must send (PUT only). */
  checksumSha256?: string;
}

export interface ResumableAppendOptions {
  offset: number;
  /** Runs after the chunk was fully received and before the new state is kept. Throw to reject the chunk. */
  beforeCommit: (bytes: number) => Promise<void> | void;
  /** Keep the bytes received before a source error (tus: store as much as possible). */
  keepPartialOnError: boolean;
  signal?: AbortSignal;
}

export interface ResumableAppendResult {
  state: Record<string, unknown>;
  bytesWritten: number;
  /** Set when the source failed. bytesWritten reflects what was kept. */
  error?: unknown;
}

/** Optional driver capability used by upload sessions. */
export interface ResumableDriver {
  create(key: string, options: { contentType: string }): Promise<Record<string, unknown>>;
  append(
    key: string,
    state: Record<string, unknown>,
    source: Readable,
    options: ResumableAppendOptions,
  ): Promise<ResumableAppendResult>;
  /** Makes the uploaded bytes available at key. */
  complete(key: string, state: Record<string, unknown>): Promise<void>;
  abort(key: string, state: Record<string, unknown>): Promise<void>;
}

/** A storage backend. Keys passed in were validated by the service with validateKey(). */
export interface StorageDriver {
  readonly name: string;
  put(key: string, body: Readable, options: DriverPutOptions): Promise<{ size: number }>;
  get(key: string, options?: { range?: ByteRange }): Promise<DriverObject>;
  head(key: string): Promise<{ size: number } | undefined>;
  /** Idempotent: deleting a missing object succeeds. */
  delete(key: string): Promise<void>;
  checkHealth(): Promise<HealthCheckResult>;
  /** Native presigned URLs (S3). Drivers without it use adapter signed URLs. */
  presign?(key: string, options: PresignOptions): Promise<string>;
  /** Moves an object to a new key (used to promote staged direct uploads). */
  move?(fromKey: string, toKey: string): Promise<void>;
  readonly resumable?: ResumableDriver;
}
